                'meta_title' => '5 Trend Teknologi 2024',
                'meta_description' => 'Panduan lengkap mengenai trend teknologi terkemuka yang melanda industri global pada tahun 2024.',
                'author_id' => $adminId,
                'is_published' => true,
                'is_featured' => true,
                'views_count' => 520,
                'published_at' => '2024-05-20 09:00:00',
